package com.skatescape;

import java.awt.event.KeyEvent;
import java.util.function.IntConsumer;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.util.HotkeyListener;

final class SkateScapeInputController {
    private final Client client;
    private final SkateScapeConfig config;
    private final KeyManager keyManager;
    private final TrickInspector trickInspector;
    private final AnimationInspector animationInspector;
    private final IntConsumer pendingTrickSlotConsumer;
    private final boolean developerToolsEnabled;

    private boolean listenersInstalled;

    private final KeyListener animationBrowseKeyListener =
            new KeyListener() {
                @Override
                public void keyTyped(KeyEvent event) {
                }

                @Override
                public void keyPressed(KeyEvent event) {
                    if (client.getGameState() != GameState.LOGGED_IN
                            || event.getComponent() != client.getCanvas()
                            || event.isControlDown()
                            || event.isAltDown()
                            || event.isShiftDown()
                            || event.isMetaDown()) {
                        return;
                    }

                    if (config.trickInspectorEnabled()) {
                        if (trickInspector != null) {
                            trickInspector.handleTrickBrowseKeyPressed(event);
                        }
                        return;
                    }

                    if (animationInspector != null) {
                        animationInspector.handleAnimationBrowseKeyPressed(event);
                    }
                }

                @Override
                public void keyReleased(KeyEvent event) {
                }
            };

    private final HotkeyListener trick1HotkeyListener;
    private final HotkeyListener trick2HotkeyListener;
    private final HotkeyListener trick3HotkeyListener;
    private final HotkeyListener trick4HotkeyListener;
    private final HotkeyListener trick5HotkeyListener;

    SkateScapeInputController(
            Client client,
            SkateScapeConfig config,
            KeyManager keyManager,
            TrickInspector trickInspector,
            AnimationInspector animationInspector,
            IntConsumer pendingTrickSlotConsumer,
            boolean developerToolsEnabled) {

        this.client = client;
        this.config = config;
        this.keyManager = keyManager;
        this.trickInspector = trickInspector;
        this.animationInspector = animationInspector;
        this.pendingTrickSlotConsumer = pendingTrickSlotConsumer;
        this.developerToolsEnabled = developerToolsEnabled;

        trick1HotkeyListener =
                createTrickHotkeyListener(
                        1,
                        () -> config.trick1Hotkey()
                );

        trick2HotkeyListener =
                createTrickHotkeyListener(
                        2,
                        () -> config.trick2Hotkey()
                );

        trick3HotkeyListener =
                createTrickHotkeyListener(
                        3,
                        () -> config.trick3Hotkey()
                );

        trick4HotkeyListener =
                createTrickHotkeyListener(
                        4,
                        () -> config.trick4Hotkey()
                );

        trick5HotkeyListener =
                createTrickHotkeyListener(
                        5,
                        () -> config.trick5Hotkey()
                );
    }

    void installListeners() {
        if (listenersInstalled) {
            return;
        }

        if (developerToolsEnabled) {
            keyManager.registerKeyListener(animationBrowseKeyListener);
        }
        keyManager.registerKeyListener(trick1HotkeyListener);
        keyManager.registerKeyListener(trick2HotkeyListener);
        keyManager.registerKeyListener(trick3HotkeyListener);
        keyManager.registerKeyListener(trick4HotkeyListener);
        keyManager.registerKeyListener(trick5HotkeyListener);

        listenersInstalled = true;
    }

    void uninstallListeners() {
        if (!listenersInstalled) {
            return;
        }

        if (developerToolsEnabled) {
            keyManager.unregisterKeyListener(animationBrowseKeyListener);
        }
        keyManager.unregisterKeyListener(trick1HotkeyListener);
        keyManager.unregisterKeyListener(trick2HotkeyListener);
        keyManager.unregisterKeyListener(trick3HotkeyListener);
        keyManager.unregisterKeyListener(trick4HotkeyListener);
        keyManager.unregisterKeyListener(trick5HotkeyListener);

        listenersInstalled = false;
    }

    private HotkeyListener createTrickHotkeyListener(
            int trickSlot,
            java.util.function.Supplier<net.runelite.client.config.Keybind>
                    keybindSupplier) {

        return new HotkeyListener(keybindSupplier) {
            @Override
            public void hotkeyPressed() {
                pendingTrickSlotConsumer.accept(trickSlot);
            }
        };
    }
}

package com.skatescape;

final class TrickDefinition {
    enum RotationProfile {
        /* Kickflip rotation curve used by Trick 1. */
        CLASSIC_FLIP,

        /*
         * Scoop -> rapid rotation -> controlled catch.
         * Intended for shove-it-family tricks.
         */
        SCOOPED_SHOVE
    }

    enum PitchProfile {
        /* Kickflip pitch: nose-up snap -> level apex -> nose-down catch. */
        CLASSIC_FLIP,

        /*
         * Much flatter deck behavior for shove-it-family tricks:
         * small scoop -> nearly flat spin -> tiny catch -> level.
         */
        FLAT_SHOVE,

        /*
         * No secondary deck pitch.
         */
        NONE
    }

    private final int slot;
    private final String name;

    /*
     * Full turns around model Z.
     *
     * +1.0 = Kickflip direction
     * -1.0 = opposite direction (useful for a future Heelflip)
     */
    private final double flipTurns;

    /*
     * Full turns around model Y.
     *
     * 0.5 = 180-degree shove-it
     * 1.0 = 360-degree shove-it
     * -1.0 = 360-degree shove-it in the opposite direction
     */
    private final double shoveTurns;

    private final RotationProfile rotationProfile;
    private final PitchProfile pitchProfile;

    TrickDefinition(
            int slot,
            String name,
            double flipTurns,
            double shoveTurns,
            RotationProfile rotationProfile,
            PitchProfile pitchProfile) {

        this.slot = slot;
        this.name = name;
        this.flipTurns = flipTurns;
        this.shoveTurns = shoveTurns;
        this.rotationProfile = rotationProfile;
        this.pitchProfile = pitchProfile;
    }

    int getSlot() {
        return slot;
    }

    String getName() {
        return name;
    }

    double getFlipTurns() {
        return flipTurns;
    }

    double getShoveTurns() {
        return shoveTurns;
    }

    RotationProfile getRotationProfile() {
        return rotationProfile;
    }

    PitchProfile getPitchProfile() {
        return pitchProfile;
    }
}

package com.skatescape;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ModelData;

@Slf4j
final class SkateboardModelFactory {
    private static final int MODEL_SCALE_BASE = 128;

    private SkateboardModelFactory() {
    }

    static ModelData createCombinedSkateboardData(
            Client client,
            int plankItemId,
            boolean showBoard,
            boolean showWheels,
            int wheelItemId,
            int wheelSizePercent,
            int wheelFrontBackOffset,
            int wheelLeftRightOffset,
            int wheelHeight) {

        final ModelData[] parts = new ModelData[5];
        int partCount = 0;

        if (showBoard) {
            final int plankModelId =
                    client.getItemDefinition(plankItemId)
                            .getInventoryModel();

            ModelData plankData = client.loadModelData(plankModelId);

            if (plankData == null) {
                log.warn("Could not load SkateScape plank model");
            } else {
                plankData = plankData.cloneVertices();

                // Sacred existing plank centering. Do not disturb. :D
                SkateboardModelGeometry.centerModel(plankData, false);

                /*
                 * keep the stock plank completely untouched and add only
                 * the missing underside.
                 *
                 * The extra copy is flattened onto the plank's real bottom
                 * plane before it is merged. Its top-face triangles therefore
                 * become a bottom cap, while the copied side faces collapse down
                 * to the perimeter instead of creating a second full plank.
                 * The cap's winding is then reversed so it renders downward.
                 *
                 * Result: original top/sides/lighting stay exactly as they were,
                 * but the deck is no longer hollow when a trick exposes it.
                 */
                final ModelData cappedPlank =
                        createBottomCappedPlank(client, plankData);

                parts[partCount++] =
                        cappedPlank != null
                                ? cappedPlank
                                : plankData;
            }
        }

        if (showWheels) {
            final ModelData[] wheelParts = createWheelParts(
                    client,
                    wheelItemId,
                    wheelSizePercent,
                    wheelFrontBackOffset,
                    wheelLeftRightOffset,
                    wheelHeight
            );

            if (wheelParts != null) {
                for (ModelData wheelPart : wheelParts) {
                    parts[partCount++] = wheelPart;
                }
            }
        }

        if (partCount == 0) {
            return null;
        }

        final ModelData combinedData =
                client.mergeModels(parts, partCount);

        if (combinedData == null) {
            log.warn("Could not merge SkateScape model");
        }

        return combinedData;
    }

    private static ModelData createBottomCappedPlank(
            Client client,
            ModelData plankData) {

        if (plankData == null) {
            return null;
        }

        final int originalFaceCount =
                plankData.getFaceCount();

        if (originalFaceCount <= 0) {
            return plankData;
        }

        /*
         * Build a second copy only as raw material for the missing bottom cap.
         * Clone vertices before changing Y so the stock plank stays untouched.
         */
        final ModelData bottomCap =
                plankData
                        .shallowCopy()
                        .cloneVertices();

        final float[] capY =
                bottomCap.getVerticesY();

        if (capY == null || capY.length == 0) {
            return plankData;
        }

        /*
         * RuneScape model Y uses negative values upward, so the largest Y is
         * the lowest point of the deck. Flatten every cap vertex onto that
         * plane. The original top-surface triangles become the missing bottom
         * surface; the copied vertical side triangles collapse to the perimeter.
         */
        float bottomY = capY[0];

        for (int i = 1; i < capY.length; i++) {
            bottomY = Math.max(bottomY, capY[i]);
        }

        for (int i = 0; i < capY.length; i++) {
            capY[i] = bottomY;
        }

        final ModelData cappedPlank =
                client.mergeModels(
                        new ModelData[] {
                                plankData,
                                bottomCap
                        },
                        2
                );

        if (cappedPlank == null) {
            return null;
        }

        final int[] faceA = cappedPlank.getFaceIndices1();
        final int[] faceB = cappedPlank.getFaceIndices2();
        final int[] faceC = cappedPlank.getFaceIndices3();

        if (faceA == null || faceB == null || faceC == null) {
            return null;
        }

        final int availableFaces = Math.min(
                cappedPlank.getFaceCount(),
                Math.min(
                        faceA.length,
                        Math.min(faceB.length, faceC.length)
                )
        );

        /*
         * The first face set is the untouched stock plank. Reverse only the
         * flattened cap set: A-B-C -> A-C-B, so the new bottom faces are visible
         * when Mike Hawk flips the deck over.
         */
        final int capFaceStart =
                originalFaceCount;

        final int capFaceEnd = Math.min(
                availableFaces,
                originalFaceCount * 2
        );

        if (capFaceEnd <= capFaceStart) {
            return null;
        }

        for (int i = capFaceStart; i < capFaceEnd; i++) {
            final int temp = faceB[i];
            faceB[i] = faceC[i];
            faceC[i] = temp;
        }

        return cappedPlank;
    }

    private static ModelData[] createWheelParts(
            Client client,
            int wheelItemId,
            int wheelSizePercent,
            int frontBack,
            int leftRight,
            int wheelHeight) {

        if (wheelItemId < 0) {
            return null;
        }

        final int wheelModelId;

        try {
            wheelModelId = client.getItemDefinition(wheelItemId)
                    .getInventoryModel();
        } catch (Exception ex) {
            log.debug(
                    "Could not resolve wheel item ID {}",
                    wheelItemId,
                    ex
            );
            return null;
        }

        final ModelData sourceWheelData =
                client.loadModelData(wheelModelId);

        if (sourceWheelData == null) {
            log.debug(
                    "Could not load wheel model for item ID {}",
                    wheelItemId
            );
            return null;
        }

        final int scale = Math.max(
                1,
                Math.round(
                        MODEL_SCALE_BASE
                                * Math.max(1, wheelSizePercent)
                                / 100.0f
                )
        );

        /*
         * Relative wheel positions:
         *
         * 0 = front-left
         * 1 = front-right
         * 2 = rear-left
         * 3 = rear-right
         *
         * Model-space conversion:
         *   X = -sideways
         *   Z = -forward
         *
         * Applying the player's yaw to the combined object turns these into
         * the intended world-relative wheel offsets.
         */
        final int[] forwardOffsets = {
                frontBack,
                frontBack,
                -frontBack,
                -frontBack
        };

        final int[] sidewaysOffsets = {
                -leftRight,
                leftRight,
                -leftRight,
                leftRight
        };

        final ModelData[] wheelParts = new ModelData[4];

        for (int i = 0; i < wheelParts.length; i++) {
            ModelData wheelData =
                    sourceWheelData.shallowCopy().cloneVertices();

            SkateboardModelGeometry.centerModel(wheelData, true);
            wheelData.scale(scale, scale, scale);

            wheelData.translate(
                    -sidewaysOffsets[i],
                    wheelHeight,
                    -forwardOffsets[i]
            );

            wheelParts[i] = wheelData;
        }

        return wheelParts;
    }
}

