                    0.0,
                    TrickDefinition.RotationProfile.CLASSIC_FLIP,
                    TrickDefinition.PitchProfile.CLASSIC_FLIP
            );

    private TrickRegistry() {
    }

    static TrickDefinition forSlot(int slot) {
        switch (slot) {
            case 1:
                return KICKFLIP;

            case 2:
                return SHOVE_IT_360;

            case 3:
                return VARIAL_KICKFLIP;

            case 4:
                return TRICK_4;

            case 5:
                return TRICK_5;

            default:
                return null;
        }
    }

    static TrickDefinition forEditorSlot(int slot) {
        return forSlot(slot);
    }
}

package com.skatescape;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;

final class Trick5BoardChoreographyController {
    static final int FRAME_COUNT = 9;

    private static final String GROUP = "skatescape";

    private final SkateScapeConfig config;
    private final ConfigManager configManager;
    private final SkateScapePlugin host;

    private final int[] x = new int[FRAME_COUNT];
    private final int[] y = new int[FRAME_COUNT];
    private final int[] z = new int[FRAME_COUNT];
    private final int[] pitch = new int[FRAME_COUNT];
    private final int[] yaw = new int[FRAME_COUNT];
    private final int[] roll = new int[FRAME_COUNT];
    private final boolean[] locked = new boolean[FRAME_COUNT];

    private int preTransitionCycles;
    private int[] frameCycles;
    private int totalCycles;

    private boolean syncingEditor;
    private boolean syncingInspector;

    Trick5BoardChoreographyController(
            SkateScapeConfig config,
            ConfigManager configManager,
            SkateScapePlugin host) {

        this.config = config;
        this.configManager = configManager;
        this.host = host;
    }

    void initialize() {
        ensureAllStoredValues();
        loadCache();
        syncEditorFromSelection();
    }

    void reset() {
        for (int frame = 1; frame <= FRAME_COUNT; frame++) {
            setStored(frame, "x", defaultValue(frame, "x"));
            setStored(frame, "y", defaultValue(frame, "y"));
            setStored(frame, "z", defaultValue(frame, "z"));
            setStored(frame, "pitch", defaultValue(frame, "pitch"));
            setStored(frame, "yaw", defaultValue(frame, "yaw"));
            setStored(frame, "roll", defaultValue(frame, "roll"));
            setFrameLocked(frame, defaultLocked(frame));
        }

        loadCache();
        syncEditorFromSelection();
        host.refreshOpenRuneLiteConfigPanel();
    }

    void updateTimeline(
            int preTransitionCycles,
            int[] playerFrameCycles,
            int totalCycles) {

        this.preTransitionCycles = Math.max(0, preTransitionCycles);
        this.frameCycles = playerFrameCycles;
        this.totalCycles = Math.max(0, totalCycles);
    }

    void onConfigChanged(ConfigChanged event) {
        if (event == null
                || !GROUP.equals(event.getGroup())) {
            return;
        }

        final String key = event.getKey();

        if ("trick5BoardFrameSlotV197".equals(key)) {
            if (!syncingEditor) {
                syncEditorFromSelection();
                syncInspectorToSelectedFrame();
                host.refreshOpenRuneLiteConfigPanel();
            }
            return;
        }

        /*
         * Inspector browsing always follows the matching board frame. The lock
         * protects the XYZ/Pitch/Yaw/Roll values stored for the selected frame;
         * it does not lock the selector itself.
         */
        if ("trickInspectorCycleV132".equals(key)
                && !syncingInspector
                && config.tuningSelectedTrick() != null
                && config.tuningSelectedTrick().getSlot() == 5) {

            syncBoardFrameFromInspectorCycle();
            return;
        }

        if ("trick5BoardFrameLockV198".equals(key)) {
            if (syncingEditor) {
                return;
            }

            setFrameLocked(
                    selectedFrame(),
                    config.trick5BoardFrameLock()
            );

            host.refreshOpenRuneLiteConfigPanel();
            return;
        }

        if (!isEditorValueKey(key)
                || syncingEditor) {
            return;
        }

        final int frame = selectedFrame();

        if (isFrameLocked(frame)) {
            syncEditorFromSelection();
            host.refreshOpenRuneLiteConfigPanel();
            return;
        }

        if (event.getNewValue() == null) {
            final String field = fieldForEditorKey(key);
            final int value = defaultValue(frame, field);

            saveEditorValue(frame, field, value);
            syncEditorFromSelection();
            host.refreshOpenRuneLiteConfigPanel();
            return;
        }

        switch (key) {
            case "trick5BoardFrameXV197":
                saveEditorValue(frame, "x", config.trick5BoardFrameX());
                break;
            case "trick5BoardFrameYV197":
                saveEditorValue(frame, "y", config.trick5BoardFrameY());
                break;
            case "trick5BoardFrameZV197":
                saveEditorValue(frame, "z", config.trick5BoardFrameZ());
                break;
            case "trick5BoardFramePitchV197":
                saveEditorValue(frame, "pitch", config.trick5BoardFramePitch());
                break;
            case "trick5BoardFrameYawV197":
                saveEditorValue(frame, "yaw", config.trick5BoardFrameYaw());
                break;
            case "trick5BoardFrameRollV197":
                saveEditorValue(frame, "roll", config.trick5BoardFrameRoll());
                break;
            default:
                break;
        }
    }

    int[] getX() {
        return x;
    }

    int[] getY() {
        return y;
    }

    int[] getZ() {
        return z;
    }

    int[] getPitch() {
        return pitch;
    }

    int[] getYaw() {
        return yaw;
    }

    int[] getRoll() {
        return roll;
    }

    boolean[] getLocked() {
        return locked;
    }

    private void syncBoardFrameFromInspectorCycle() {
        final int frame = frameForInspectorCycle(
                config.trickInspectorCycle()
        );

        if (frame != selectedFrame()) {
            syncingEditor = true;
            try {
                configManager.setConfiguration(
                        GROUP,
                        "trick5BoardFrameSlotV197",
                        SkateScapeConfig.BoardFrameSlot.fromSlot(frame).name()
                );
            } finally {
                syncingEditor = false;
            }
        }

        syncEditorFromFrame(frame);
        host.refreshOpenRuneLiteConfigPanel();
    }

    private void syncInspectorToSelectedFrame() {
        if (syncingInspector
                || frameCycles == null
                || frameCycles.length == 0) {
            return;
        }

        final int cycle = frameStartCycle(selectedFrame());

        syncingInspector = true;
        try {
            if (config.tuningSelectedTrick() == null
                    || config.tuningSelectedTrick().getSlot() != 5) {
                configManager.setConfiguration(
                        GROUP,
                        "inspectorSelectedTrickV132",
                        SkateScapeConfig.TrickSelection.TRICK_5.name()
                );
            }

            configManager.setConfiguration(
                    GROUP,
                    "trickInspectorCycleV132",
                    cycle
            );
        } finally {
            syncingInspector = false;
        }
    }

    private int frameForInspectorCycle(int inspectorCycle) {
        if (frameCycles == null
                || frameCycles.length == 0) {
            return selectedFrame();
        }

        int safeCycle = Math.max(0, inspectorCycle);
        if (totalCycles > 0) {
            safeCycle = Math.min(totalCycles, safeCycle);
        }

        final int mainElapsed = safeCycle - preTransitionCycles;

        if (mainElapsed <= 0) {
            return 1;
        }

        int cycle = 0;
        final int count = Math.min(FRAME_COUNT, frameCycles.length);

        for (int i = 0; i < count; i++) {
            cycle += Math.max(1, frameCycles[i]);

            if (mainElapsed < cycle) {
                return i + 1;
            }
        }

        return count > 0
                ? count
                : 1;
    }

    private int frameStartCycle(int frame) {
        int cycle = preTransitionCycles;

        if (frameCycles == null) {
            return Math.max(0, cycle);
        }

        final int stop = Math.min(
                Math.max(0, frame - 1),
                frameCycles.length
        );

        for (int i = 0; i < stop; i++) {
            cycle += Math.max(1, frameCycles[i]);
        }

        cycle = Math.max(0, cycle);
        if (totalCycles > 0) {
            cycle = Math.min(totalCycles, cycle);
        }

        return cycle;
    }

    private void saveEditorValue(
            int frame,
            String field,
            int value) {

        final int safeValue =
                field.equals("pitch")
                        || field.equals("yaw")
                        || field.equals("roll")
                        ? clamp(value, -180, 180)
                        : clamp(value, -256, 256);

        setStored(frame, field, safeValue);
        setCached(frame, field, safeValue);
    }

    private void syncEditorFromSelection() {
        syncEditorFromFrame(selectedFrame());
    }

    private void syncEditorFromFrame(int frame) {
        final int safeFrame = clamp(frame, 1, FRAME_COUNT);

        syncingEditor = true;
        try {
            configManager.setConfiguration(
                    GROUP,
                    "trick5BoardFrameXV197",
                    getStored(safeFrame, "x")
            );
            configManager.setConfiguration(
                    GROUP,
                    "trick5BoardFrameYV197",
                    getStored(safeFrame, "y")
            );
            configManager.setConfiguration(
                    GROUP,
                    "trick5BoardFrameZV197",
                    getStored(safeFrame, "z")
            );
            configManager.setConfiguration(
                    GROUP,
                    "trick5BoardFramePitchV197",
                    getStored(safeFrame, "pitch")
            );
            configManager.setConfiguration(
                    GROUP,
                    "trick5BoardFrameYawV197",
                    getStored(safeFrame, "yaw")
            );
            configManager.setConfiguration(
                    GROUP,
                    "trick5BoardFrameRollV197",
                    getStored(safeFrame, "roll")
            );
            configManager.setConfiguration(
                    GROUP,
                    "trick5BoardFrameLockV198",
                    isFrameLocked(safeFrame)
            );
        } finally {
            syncingEditor = false;
        }
    }

    private void ensureAllStoredValues() {
        for (int frame = 1; frame <= FRAME_COUNT; frame++) {
            for (String field : new String[]{"x", "y", "z", "pitch", "yaw", "roll"}) {
                final String key = storageKey(frame, field);
                final String existing = configManager.getConfiguration(GROUP, key);

                if (existing == null
                        || existing.trim().isEmpty()) {
                    setStored(
                            frame,
                            field,
                            defaultValue(frame, field)
                    );
                }
            }
        }
    }

    private void loadCache() {
        for (int frame = 1; frame <= FRAME_COUNT; frame++) {
            x[frame - 1] = getStored(frame, "x");
            y[frame - 1] = getStored(frame, "y");
            z[frame - 1] = getStored(frame, "z");
            pitch[frame - 1] = getStored(frame, "pitch");
            yaw[frame - 1] = getStored(frame, "yaw");
            roll[frame - 1] = getStored(frame, "roll");
            locked[frame - 1] = isFrameLocked(frame);
        }
    }

    private int getStored(
            int frame,
            String field) {

        final String raw =
                configManager.getConfiguration(
                        GROUP,
                        storageKey(frame, field)
                );

        return parseOrDefault(
                raw,
                defaultValue(frame, field)
        );
    }

    private int parseOrDefault(
            String raw,
            int fallback) {

        if (raw == null
                || raw.trim().isEmpty()) {
            return fallback;
        }

        try {
            return Integer.parseInt(raw.trim());
        } catch (NumberFormatException ignored) {
            return fallback;
        }
    }

    private void setStored(
            int frame,
            String field,
            int value) {

        configManager.setConfiguration(
                GROUP,
                storageKey(frame, field),
                value
        );
    }

    private void setCached(
            int frame,
            String field,
            int value) {

        final int index = clamp(frame, 1, FRAME_COUNT) - 1;

        switch (field) {
            case "x":
                x[index] = value;
                break;
            case "y":
                y[index] = value;
                break;
            case "z":
                z[index] = value;
                break;
            case "pitch":
                pitch[index] = value;
                break;
            case "yaw":
                yaw[index] = value;
                break;
            case "roll":
                roll[index] = value;
                break;
            default:
                break;
        }
    }

    private int selectedFrame() {
        final SkateScapeConfig.BoardFrameSlot selected =
                config.trick5BoardFrameSlot();

        return selected == null
                ? 5
                : clamp(selected.getSlot(), 1, FRAME_COUNT);
    }

    private int defaultValue(
            int frame,
            String field) {

        if (frame == 4 || frame == 6) {
            switch (field) {
                case "x":
                    return 50;
                case "y":
                    return 100;
                case "z":
                    return 10;
                case "pitch":
                    return 30;
                case "roll":
                    return 145;
                default:
                    return 0;
            }
        }

        if (frame == 5) {
            switch (field) {
                case "x":
                    return 88;
                case "y":
                    return 220;
                case "z":
                    return 17;
                case "pitch":
                    return 60;
                case "roll":
                    return 170;
                default:
                    return 0;
            }
        }

        return 0;
    }

    private boolean defaultLocked(int frame) {
        return clamp(frame, 1, FRAME_COUNT) == 5;
    }

    private boolean isFrameLocked(int frame) {
        final String raw =
                configManager.getConfiguration(
                        GROUP,
                        frameLockStorageKey(frame)
                );

        if (raw == null || raw.trim().isEmpty()) {
            return defaultLocked(frame);
        }

        return Boolean.parseBoolean(raw);
    }

    private void setFrameLocked(
            int frame,
            boolean locked) {

        final int safeFrame = clamp(frame, 1, FRAME_COUNT);

        configManager.setConfiguration(
                GROUP,
                frameLockStorageKey(safeFrame),
                locked
        );

        this.locked[safeFrame - 1] = locked;
    }

    private String frameLockStorageKey(int frame) {
        return "v199_t5_board_frame_"
                + clamp(frame, 1, FRAME_COUNT)
                + "_locked";
    }

    private String storageKey(
            int frame,
            String field) {

        return "v197_t5_board_frame_"
                + clamp(frame, 1, FRAME_COUNT)
                + "_"
                + field;
    }

    private String fieldForEditorKey(String key) {
        switch (key) {
            case "trick5BoardFrameXV197":
                return "x";
            case "trick5BoardFrameYV197":
                return "y";
            case "trick5BoardFrameZV197":
                return "z";
            case "trick5BoardFramePitchV197":
                return "pitch";
            case "trick5BoardFrameYawV197":
                return "yaw";
            case "trick5BoardFrameRollV197":
                return "roll";
            default:
                return "x";
        }
    }

    private boolean isEditorValueKey(String key) {
        return "trick5BoardFrameXV197".equals(key)
                || "trick5BoardFrameYV197".equals(key)
                || "trick5BoardFrameZV197".equals(key)
                || "trick5BoardFramePitchV197".equals(key)
                || "trick5BoardFrameYawV197".equals(key)
                || "trick5BoardFrameRollV197".equals(key);
    }

    private static int clamp(
            int value,
            int min,
            int max) {

        return Math.max(min, Math.min(max, value));
    }
}

package com.skatescape;

import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

// The weird skateboard tricks remain Mike Hawk's problem. :D
final class SkateboardSceneController {
    @FunctionalInterface
    interface TransformApplier {
        void apply(double terrainPitch, double terrainRoll);
    }

    private static final double ORIENTATION_TO_RADIANS =
            (Math.PI * 2.0) / 2048.0;

    private final Client client;

    private final int plankItemId;
    private final boolean showBoard;
    private final boolean showWheels;
    private final int wheelItemId;
    private final int wheelSizePercent;
    private final int wheelFrontBackOffset;
    private final int wheelLeftRightOffset;
    private final int wheelHeight;

    private final int terrainSampleForward;
    private final int terrainSampleSideways;
    private final double maxTerrainTiltRadians;
    private final double terrainAngleQuantization;

    private RuneLiteObject board;
    private ModelData baseSkateboardData;

    private int appliedTerrainPitchKey = Integer.MIN_VALUE;
    private int appliedTerrainRollKey = Integer.MIN_VALUE;
    private boolean terrainTiltApplied;
    private boolean trickTransformApplied;

    SkateboardSceneController(
            Client client,
            int plankItemId,
            boolean showBoard,
            boolean showWheels,
            int wheelItemId,
            int wheelSizePercent,
            int wheelFrontBackOffset,
            int wheelLeftRightOffset,
            int wheelHeight,
            int terrainSampleForward,
            int terrainSampleSideways,
            double maxTerrainTiltRadians,
            double terrainAngleQuantization) {

        this.client = client;
        this.plankItemId = plankItemId;
        this.showBoard = showBoard;
        this.showWheels = showWheels;
        this.wheelItemId = wheelItemId;
        this.wheelSizePercent = wheelSizePercent;
        this.wheelFrontBackOffset = wheelFrontBackOffset;
        this.wheelLeftRightOffset = wheelLeftRightOffset;
        this.wheelHeight = wheelHeight;
        this.terrainSampleForward = terrainSampleForward;
        this.terrainSampleSideways = terrainSampleSideways;
        this.maxTerrainTiltRadians = maxTerrainTiltRadians;
        this.terrainAngleQuantization = terrainAngleQuantization;
    }

    void update(
            Player player,
            LocalPoint boardLocation,
            boolean trickActive,
            TransformApplier transformApplier) {

        if (player == null || boardLocation == null) {
            return;
        }

        if (board == null) {
            createSkateboard(player, boardLocation);
        }

        if (board == null) {
            return;
        }

        final WorldView worldView = player.getWorldView();

        board.setWorldView(worldView.getId());
        board.setLocation(
                boardLocation,
                worldView.getPlane()
        );
        board.setOrientation(player.getCurrentOrientation());

        updateTerrainTilt(
                player,
                boardLocation,
                worldView.getPlane(),
                trickActive,
                transformApplier
        );
    }

    ModelData createWorkingModelData() {
        if (baseSkateboardData == null) {
            return null;
        }

        return baseSkateboardData
                .shallowCopy()
                .cloneVertices();
    }

    void setModel(Model model) {
        if (board != null && model != null) {
            board.setModel(model);
        }
    }

    void markTransformApplied(boolean trickActive) {
        trickTransformApplied = trickActive;
    }

    void clearTrickTransformApplied() {
        trickTransformApplied = false;
    }

    void removeBoard() {
        if (board != null) {
            board.setActive(false);
            board = null;
        }

        baseSkateboardData = null;
        appliedTerrainPitchKey = Integer.MIN_VALUE;
        appliedTerrainRollKey = Integer.MIN_VALUE;
        terrainTiltApplied = false;
        trickTransformApplied = false;
    }

    private void createSkateboard(
            Player player,
            LocalPoint boardLocation) {

        removeBoard();

        final ModelData combinedData =
                SkateboardModelFactory.createCombinedSkateboardData(
                        client,
                        plankItemId,
                        showBoard,
                        showWheels,
                        wheelItemId,
                        wheelSizePercent,
                        wheelFrontBackOffset,
                        wheelLeftRightOffset,
                        wheelHeight
                );

        if (combinedData == null) {
            return;
        }

        baseSkateboardData = combinedData;

        appliedTerrainPitchKey = Integer.MIN_VALUE;
        appliedTerrainRollKey = Integer.MIN_VALUE;
        terrainTiltApplied = false;
        trickTransformApplied = false;

        final WorldView worldView = player.getWorldView();

        board = client.createRuneLiteObject();
        board.setModel(combinedData.light());
        board.setWorldView(worldView.getId());
        board.setLocation(
                boardLocation,
                worldView.getPlane()
        );
        board.setOrientation(player.getCurrentOrientation());
        board.setActive(true);
    }

    /*
     * TERRAIN FOLLOWING
     *
     * The skateboard remains one rigid model. Sample terrain in the board's
     * local front/rear/left/right directions, calculate pitch and roll, then
     * hand those exact angles to SkateboardTrickTransformController's
     * transform pipeline.
     */
    private void updateTerrainTilt(
            Player player,
            LocalPoint boardLocation,
            int plane,
            boolean trickActive,
            TransformApplier transformApplier) {

        if (board == null
                || baseSkateboardData == null
                || transformApplier == null) {
            return;
        }

        /*
         * All four samples share the same player orientation. Calculate the
         * trigonometry once instead of repeating sin/cos for every point.
         */
        final double angle =
                player.getCurrentOrientation()
                        * ORIENTATION_TO_RADIANS;
        final double sin = Math.sin(angle);
        final double cos = Math.cos(angle);

        final LocalPoint frontPoint = offsetRelativeToOrientation(
                boardLocation,
                terrainSampleForward,
                0,
                sin,
                cos
        );

        final LocalPoint rearPoint = offsetRelativeToOrientation(
                boardLocation,
                -terrainSampleForward,
                0,
                sin,
                cos
        );

        final LocalPoint leftPoint = offsetRelativeToOrientation(
                boardLocation,
                0,
                -terrainSampleSideways,
                sin,
                cos
        );

        final LocalPoint rightPoint = offsetRelativeToOrientation(
                boardLocation,
                0,
                terrainSampleSideways,
                sin,
                cos
        );

        final int frontHeight =
                Perspective.getTileHeight(client, frontPoint, plane);
        final int rearHeight =
                Perspective.getTileHeight(client, rearPoint, plane);
        final int leftHeight =
                Perspective.getTileHeight(client, leftPoint, plane);
        final int rightHeight =
                Perspective.getTileHeight(client, rightPoint, plane);

        /*
         * Model-space mapping:
         *
         * front  = negative Z
         * rear   = positive Z
         * left   = positive X
         * right  = negative X
         */
        double pitch = Math.atan2(
                frontHeight - rearHeight,
                terrainSampleForward * 2.0
        );

        double roll = Math.atan2(
                leftHeight - rightHeight,
                terrainSampleSideways * 2.0
        );

        pitch = clamp(
                pitch,
                -maxTerrainTiltRadians,
                maxTerrainTiltRadians
        );

        roll = clamp(
                roll,
                -maxTerrainTiltRadians,
                maxTerrainTiltRadians
        );

        /*
         * Quantize very slightly so microscopic floating-point noise does not
         * rebuild the board model every client tick.
         */
        final int pitchKey = (int) Math.round(
                pitch * terrainAngleQuantization
        );

        final int rollKey = (int) Math.round(
                roll * terrainAngleQuantization
        );

        if (!trickActive
                && !trickTransformApplied
                && terrainTiltApplied
                && pitchKey == appliedTerrainPitchKey
                && rollKey == appliedTerrainRollKey) {
            return;
        }

        transformApplier.apply(
                pitch,
                roll
        );

        appliedTerrainPitchKey = pitchKey;
        appliedTerrainRollKey = rollKey;
        terrainTiltApplied = true;
    }

    static LocalPoint offsetRelativeToPlayer(
            Player player,
            LocalPoint origin,
            int forward,
            int sideways) {

        final double angle =
                player.getCurrentOrientation()
                        * ORIENTATION_TO_RADIANS;

        return offsetRelativeToOrientation(
                origin,
                forward,
                sideways,
                Math.sin(angle),
                Math.cos(angle)
        );
    }

    private static LocalPoint offsetRelativeToOrientation(
            LocalPoint origin,
            int forward,
            int sideways,
            double sin,
            double cos) {

        final int offsetX = (int) Math.round(
                -sin * forward
                        - cos * sideways
        );

        final int offsetY = (int) Math.round(
                -cos * forward
                        + sin * sideways
        );

        return origin.plus(offsetX, offsetY);
    }

    private static double clamp(
            double value,
            double min,
            double max) {

        return Math.max(min, Math.min(max, value));
    }
}

package com.skatescape;

import java.awt.event.KeyEvent;
import java.util.function.IntPredicate;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.config.ConfigManager;

@Slf4j
final class AnimationInspector {
    private final Client client;
    private final SkateScapeConfig config;
    private final ConfigManager configManager;
    private final Runnable refreshOpenConfigPanel;
    private final Runnable applyOpenConfigPanelFixes;
    private final int maxSafeAnimationId;

    /*
     * Animation Inspector has its own temporary smoothing wrapper.
     * It stays separate from SkateScape's normal raw-playback filter.
     *
     * freezeFrame ON  -> exclude only the tested animation
     * freezeFrame OFF -> restore RuneLite's original smoothing filter
     */
    private IntPredicate previousInterpolationFilter;
    private IntPredicate interpolationFilter;
    private boolean interpolationFilterInstalled;
    private int interpolationExcludedId = -1;

    private volatile int pendingAnimationIdDelta;
    private volatile int pendingAnimationFrameDelta;

    private int animationBrowseMaxFrame = -1;
    private int animationTestId;
    private int animationTestFrame;

    AnimationInspector(
            Client client,
            SkateScapeConfig config,
            ConfigManager configManager,
            Runnable refreshOpenConfigPanel,
            Runnable applyOpenConfigPanelFixes,
            int maxSafeAnimationId) {

        this.client = client;
        this.config = config;
        this.configManager = configManager;
        this.refreshOpenConfigPanel = refreshOpenConfigPanel;
        this.applyOpenConfigPanelFixes = applyOpenConfigPanelFixes;
        this.maxSafeAnimationId = maxSafeAnimationId;
    }

    void syncFromConfig() {
        animationTestId = config.animationId();
        animationTestFrame = config.animationFrame();
    }

    int getBrowseMaxFrame() {
        return animationBrowseMaxFrame;
    }

    /**
     * Called only after SkateScapePlugin has applied the shared inspector key
     * guards (logged in, canvas focused, no modifiers, Trick Inspector first).
     */
    boolean handleAnimationBrowseKeyPressed(KeyEvent event) {
        if (!config.animationTest()) {
            return false;
        }

        switch (event.getKeyCode()) {
            case KeyEvent.VK_UP:
                pendingAnimationIdDelta++;
                event.consume();
                return true;

            case KeyEvent.VK_DOWN:
                pendingAnimationIdDelta--;
                event.consume();
                return true;

            case KeyEvent.VK_RIGHT:
                pendingAnimationFrameDelta++;
                event.consume();
                return true;

            case KeyEvent.VK_LEFT:
                pendingAnimationFrameDelta--;
                event.consume();
                return true;

            default:
                return false;
        }
    }

    void clearBrowseState() {
        pendingAnimationIdDelta = 0;
        pendingAnimationFrameDelta = 0;
        animationBrowseMaxFrame = -1;
    }

    private void setAnimationTestId(int animationId) {
        animationTestId = animationId;
        configManager.setConfiguration(
                "skatescape",
                "animationId",
                animationId
        );
    }

    private void setAnimationTestFrame(int animationFrame) {
        animationTestFrame = animationFrame;
        configManager.setConfiguration(
                "skatescape",
                "animationFrame",
                animationFrame
        );
    }

    private Animation loadSafeAnimation(int animationId) {
        if (animationId < 0
                || animationId > maxSafeAnimationId) {
            return null;
        }

        try {
            final Animation animation =
                    client.loadAnimation(animationId);

            if (animation == null
                    || animation.getNumFrames() <= 0) {
                return null;
            }

            return animation;
        } catch (RuntimeException ex) {
            log.debug(
                    "Skipping unsafe/nonexistent animation {}",
                    animationId,
                    ex
            );
            return null;
        }
    }

    private int findNextValidAnimationId(
            int currentId,
            int direction) {

        if (direction == 0) {
            return currentId;
        }

        int candidate =
                currentId + Integer.signum(direction);

        while (candidate >= 0
                && candidate <= maxSafeAnimationId) {

            if (loadSafeAnimation(candidate) != null) {
                return candidate;
            }

            candidate += Integer.signum(direction);
        }

        return currentId;
    }

    private int getSafeMaxFrame(Animation animation) {
        if (animation == null) {
            return 0;
        }

        return Math.max(
                0,
                animation.getNumFrames() - 1
        );
    }

    private void clampAnimationTestFrame(Animation animation) {
        final int maxFrame =
                getSafeMaxFrame(animation);

        final int previousMaxFrame =
                animationBrowseMaxFrame;

        animationBrowseMaxFrame = maxFrame;

        if (config.animationTest()
                && previousMaxFrame != maxFrame) {
            applyOpenConfigPanelFixes.run();
        }

        final int safeFrame =
                Math.max(
                        0,
                        Math.min(
                                animationTestFrame,
                                maxFrame
                        )
                );

        if (safeFrame != animationTestFrame) {
            setAnimationTestFrame(safeFrame);
        }
    }

    void handleBrowseRequest() {
        int animationDelta =
                pendingAnimationIdDelta;

        int frameDelta =
                pendingAnimationFrameDelta;

        pendingAnimationIdDelta = 0;
        pendingAnimationFrameDelta = 0;

        boolean visibleConfigChanged = false;

        if (animationDelta != 0) {
            int animationId =
                    animationTestId;

            final int direction =
                    Integer.signum(animationDelta);

            for (int i = 0;
                    i < Math.abs(animationDelta);
                    i++) {

                final int nextAnimationId =
                        findNextValidAnimationId(
                                animationId,
                                direction
                        );

                if (nextAnimationId == animationId) {
                    break;
                }

                animationId = nextAnimationId;
            }

            if (animationId != animationTestId) {
                setAnimationTestId(animationId);
                visibleConfigChanged = true;

                final Animation animation =
                        loadSafeAnimation(animationId);

                final int oldFrame = animationTestFrame;
                clampAnimationTestFrame(animation);
                visibleConfigChanged |=
                        animationTestFrame != oldFrame;
            }
        }

        if (frameDelta != 0) {
            final Animation animation =
                    loadSafeAnimation(
                            animationTestId
                    );

            if (animation != null) {
                final int maxFrame =
                        getSafeMaxFrame(animation);

                animationBrowseMaxFrame = maxFrame;

                final int safeFrame =
                        Math.max(
                                0,
                                Math.min(
                                        animationTestFrame
                                                + frameDelta,
                                        maxFrame
                                )
                        );

                if (safeFrame != animationTestFrame) {
                    setAnimationTestFrame(safeFrame);
                    visibleConfigChanged = true;
                }
            }
        }

        if (visibleConfigChanged) {
            refreshOpenConfigPanel.run();
        }
    }

    private void updateInterpolationFilter(int animationId) {
        /*
         * Full action-animation playback keeps RuneLite Animation Smoothing
         * completely untouched.
         */
        if (!config.freezeFrame()) {
            restoreInterpolationFilter();
            return;
        }

        final IntPredicate currentFilter =
                client.getAnimationInterpolationFilter();

        /*
         * Animation Smoothing is off (or there is no active interpolation
         * filter). There is nothing for SkateScape to suppress.
         */
        if (!interpolationFilterInstalled
                && currentFilter == null) {

            previousInterpolationFilter = null;
            interpolationExcludedId = -1;
            return;
        }

        /*
         * If another plugin replaces the filter while the tester wrapper is
         * active, drop ownership instead of restoring stale state.
         */
        if (interpolationFilterInstalled
                && currentFilter != interpolationFilter) {

            previousInterpolationFilter = currentFilter;
            interpolationFilter = null;
            interpolationFilterInstalled = false;
            interpolationExcludedId = -1;
        }

        /*
         * Same frozen animation with the wrapper still installed; no rebuild
         * is needed.
         */
        if (interpolationFilterInstalled
                && currentFilter == interpolationFilter
                && interpolationExcludedId == animationId) {

            return;
        }

        /*
         * When the tested animation changes while frozen, rebuild from the
         * original RuneLite filter instead of the previous wrapper.
         */
        if (interpolationFilterInstalled
                && currentFilter == interpolationFilter) {

            client.setAnimationInterpolationFilter(
                    previousInterpolationFilter
            );

            interpolationFilter = null;
            interpolationFilterInstalled = false;
            interpolationExcludedId = -1;
        }

        final IntPredicate baseFilter =
                client.getAnimationInterpolationFilter();

        if (baseFilter == null) {
            previousInterpolationFilter = null;
            return;
        }

        previousInterpolationFilter =
                baseFilter;

        interpolationExcludedId =
                animationId;

        interpolationFilter =
                candidateAnimationId ->
                        candidateAnimationId != animationId
                                && baseFilter.test(candidateAnimationId);

        client.setAnimationInterpolationFilter(
                interpolationFilter
        );

        interpolationFilterInstalled = true;
    }

    void restoreInterpolationFilter() {
        if (!interpolationFilterInstalled) {
            previousInterpolationFilter = null;
            interpolationFilter = null;
            interpolationExcludedId = -1;
            return;
        }

        /*
         * Restore only while this wrapper is still installed. Do not overwrite
         * a filter installed later by another plugin.
         */
        if (client.getAnimationInterpolationFilter()
                == interpolationFilter) {

            client.setAnimationInterpolationFilter(
                    previousInterpolationFilter
            );
        }

        previousInterpolationFilter = null;
        interpolationFilter = null;
        interpolationFilterInstalled = false;
        interpolationExcludedId = -1;
    }

    void update(Player player) {
        int animationId =
                animationTestId;

        /*
         * Protect against old saved values or manual edits outside the
         * current cache range. Never apply an unchecked animation ID to
         * the player.
         */
        if (animationId < 0
                || animationId > maxSafeAnimationId) {

            animationId =
                    Math.max(
                            0,
                            Math.min(
                                    animationId,
                                    maxSafeAnimationId
                            )
                    );

            Animation animation =
                    loadSafeAnimation(animationId);

            if (animation == null) {
                int fallback =
                        findNextValidAnimationId(
                                animationId,
                                -1
                        );

                if (fallback == animationId) {
                    fallback =
                            findNextValidAnimationId(
                                    animationId,
                                    1
                            );
                }

                animationId = fallback;
                animation = loadSafeAnimation(animationId);
            }

            if (animation == null) {
                return;
            }

            setAnimationTestId(animationId);
            clampAnimationTestFrame(animation);
            return;
        }

        final Animation animation =
                loadSafeAnimation(animationId);

        if (animation == null) {
            /*
             * A hole/nonexistent sequence inside the numeric range is
             * simply ignored rather than being applied to the player.
             * Arrow browsing will skip over it automatically.
             */
            animationBrowseMaxFrame = -1;
            restoreInterpolationFilter();
            return;
        }

        clampAnimationTestFrame(animation);
        updateInterpolationFilter(animationId);

        final int safeFrame =
                Math.max(
                        0,
                        Math.min(
                                animationTestFrame,
                                getSafeMaxFrame(animation)
                        )
                );

        /*
         * Simplified Animation Testing modes:
         *
         * Freeze frame ON  -> exact pose-frame, smoothing suppressed only for
         *                     this tested animation
         * Freeze frame OFF -> normal action animation with RuneLite smoothing
         *                     untouched
         */
        if (config.freezeFrame()) {
            if (player.getPoseAnimation() != animationId) {
                player.setPoseAnimation(animationId);
            }

            player.setPoseAnimationFrame(safeFrame);
        } else {
            if (player.getAnimation() != animationId) {
                player.setAnimation(animationId);
            }
        }
    }
}

package com.skatescape;

import java.util.Locale;
import net.runelite.api.gameval.AnimationID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;

final class PerTrickConfigController {
    private final SkateScapeConfig config;
    private final ConfigManager configManager;
    private final SkateScapePlugin host;

    /* Developer inspector modes are mutually exclusive. */
    private boolean syncingInspectorModes;

    PerTrickConfigController(
            SkateScapeConfig config,
            ConfigManager configManager,
            SkateScapePlugin host) {

        this.config = config;
        this.configManager = configManager;
        this.host = host;
    }

    void initializeStorage() {
        initializeCurrentPerTrickStorage();
        initializePoseTimingMilliseconds();
        mirrorSharedTrickSelectionFromTuning();
        syncAllEditorsFromSelection();
    }

    /*
     * PER-TRICK EDITORS.
     *
     * RuneLite config items are static, so each editor section uses one
     * visible set of controls plus hidden per-trick backing keys. Changing a
     * section's Trick dropdown swaps the visible values immediately. Runtime
     * playback always reads the backing values for the trick actually being
     * performed, regardless of which editor is currently open.
     */
    private boolean syncingPerTrickEditor;
    private boolean syncingSharedTrickSelection;

    private String perTrickKey(
            int slot,
            String family,
            String field) {

        return "v132_t"
                + clampInt(slot, 1, 5)
                + "_"
                + family
                + "_"
                + field;
    }

    private String getConfigString(
            String key,
            String fallback) {

        final String value =
                configManager.getConfiguration(
                        "skatescape",
                        key
                );

        return value == null
                || value.trim().isEmpty()
                        ? fallback
                        : value;
    }

    private int getConfigInt(
            String key,
            int fallback) {

        final String value =
                configManager.getConfiguration(
                        "skatescape",
                        key
                );

        if (value == null
                || value.trim().isEmpty()) {

            return fallback;
        }

        try {
            return Integer.parseInt(value.trim());
        } catch (NumberFormatException ignored) {
            return fallback;
        }
    }

    private double getConfigDouble(
            String key,
            double fallback) {

        final String value =
                configManager.getConfiguration(
                        "skatescape",
                        key
                );

        if (value == null
                || value.trim().isEmpty()) {

            return fallback;
        }

        try {
            return Double.parseDouble(value.trim());
        } catch (NumberFormatException ignored) {
            return fallback;
        }
    }

    private boolean getConfigBoolean(
            String key,
            boolean fallback) {

        final String value =
                configManager.getConfiguration(
                        "skatescape",
                        key
                );

        if (value == null
                || value.trim().isEmpty()) {

            return fallback;
        }

        return Boolean.parseBoolean(value.trim());
    }

    private void ensureConfigValue(
            String key,
            Object value) {

        final String existing =
                configManager.getConfiguration(
                        "skatescape",
                        key
                );

        if (existing == null
                || existing.trim().isEmpty()) {

            configManager.setConfiguration(
                    "skatescape",
                    key,
                    value
            );
        }
    }
    private int defaultTuningInt(
            int slot,
            String field) {

        switch (field) {
            case "durationMs":
                return defaultMainDurationMs(slot);
            case "popHeight":
                if (slot == 5) {
                    return 128;
                }
                return slot == 4 ? 50 : 60;
            default:
                return 0;
        }
    }
    private int defaultMainDurationMs(int slot) {
        /* Tricks 4 and 5 use a 1420 ms canonical MAIN duration. */
        if (slot == 4) {
            return 1420;
        }

        if (slot == 5) {
            return 1420;
        }

        return 900;
    }

    private int defaultMainCycles(int slot) {
        return Math.max(
                1,
                (int) Math.round(defaultMainDurationMs(slot) / 20.0)
        );
    }

    private int currentMainCyclesForQueueDefault(int slot) {
        final int safeSlot = clampInt(slot, 1, 5);

        int targetCycles =
                Math.max(
                        1,
                        (int) Math.round(
                                Math.max(
                                        300,
                                        getTuningInt(safeSlot, "durationMs")
                                ) / 20.0
                        )
                );

        targetCycles =
                Math.max(
                        targetCycles,
                        SkateScapePlugin.DEFAULT_TRICK_JUMP_FRAMES.length
                );

        if (safeSlot == 4
                || !usesLegacyPlayerPose(safeSlot)) {

            targetCycles =
                    Math.max(
                            targetCycles,
                            clampInt(
                                    getPoseLength(safeSlot),
                                    1,
                                    maxPoseSequenceLength(safeSlot)
                            )
                    );
        }

        return targetCycles;
    }
    /*
     * DURATION-AWARE QUEUE POSITIONS.
     *
     * The visible editor still uses the exact complete-timeline cycle shown by
     * Trick Inspector. Hidden storage uses one compact normalized coordinate:
     *
     *   0.x = PRE, 1.x = MAIN, 2.x = landing seam, 3.x = RETURN
     *
     * The fractional part is the position inside that phase. Only MAIN changes
     * length with Trick duration, so a splice chosen while slowed down stays on
     * the same visual pose when normal speed is restored.
     */
    private int transitionCycles(
            int[] frames,
            int[] durationsMs) {

        int total = 0;
        for (int i = 0; i < frames.length; i++) {
            total += Math.max(
                    1,
                    (int) Math.round(
                            durationsMs[Math.min(i, durationsMs.length - 1)]
                                    / 20.0
                    )
            );
        }
        return Math.max(1, total);
    }

    private int[] queuePhaseCycles(int slot) {
        return new int[]{
                transitionCycles(
                        SkateScapePlugin.DEFAULT_TRICK_PRE_FRAMES,
                        SkateScapePlugin.DEFAULT_TRICK_PRE_DURATIONS_MS
                ),
                currentMainCyclesForQueueDefault(slot),
                Math.max(
                        1,
                        (int) Math.round(
                                SkateScapePlugin.DEFAULT_TRICK_POST_SEAM_DURATION_MS
                                        / 20.0
                        )
                ),
                transitionCycles(
                        SkateScapePlugin.DEFAULT_TRICK_POST_FRAMES,
                        SkateScapePlugin.DEFAULT_TRICK_POST_DURATIONS_MS
                )
        };
    }

    private String queuePositionKey(
            int slot,
            String side) {

        return perTrickKey(
                slot,
                "queue",
                side + "PositionV184"
        );
    }

    private boolean hasQueuePosition(
            int slot,
            String side) {

        final String value =
                configManager.getConfiguration(
                        "skatescape",
                        queuePositionKey(slot, side)
                );

        return value != null && !value.trim().isEmpty();
    }

    private void storeQueuePosition(
            int slot,
            String side,
            int requestedCycle) {

        final int safeSlot = clampInt(slot, 1, 5);
        final int[] lengths = queuePhaseCycles(safeSlot);
        int total = 0;
        for (int length : lengths) {
            total += length;
        }

        final int cycle =
                clampInt(
                        requestedCycle,
                        0,
                        Math.max(0, total - 1)
                );

        int phase = 0;
        int phaseStart = 0;
        while (phase < lengths.length - 1
                && cycle >= phaseStart + lengths[phase]) {
            phaseStart += lengths[phase++];
        }

        final double position =
                phase
                        + (cycle - phaseStart)
                                / (double) Math.max(1, lengths[phase]);

        configManager.setConfiguration(
                "skatescape",
                queuePositionKey(safeSlot, side),
                position
        );

        /* Keep the raw-cycle key as a readable/cache value. */
        setPerTrickConfig(
                safeSlot,
                "queue",
                side + "Cycle",
                cycle
        );
    }

    private int getQueuePositionCycle(
            int slot,
            String side,
            int rawFallback) {

        final int safeSlot = clampInt(slot, 1, 5);
        final int[] lengths = queuePhaseCycles(safeSlot);
        int total = 0;
        for (int length : lengths) {
            total += length;
        }

        if (!hasQueuePosition(safeSlot, side)) {
            return clampInt(rawFallback, 0, Math.max(0, total - 1));
        }

        final double position =
                clampDouble(
                        getConfigDouble(
                                queuePositionKey(safeSlot, side),
                                1.0
                        ),
                        0.0,
                        3.999999
                );

        final int phase =
                clampInt(
                        (int) Math.floor(position),
                        0,
                        lengths.length - 1
                );

        int phaseStart = 0;
        for (int i = 0; i < phase; i++) {
            phaseStart += lengths[i];
        }

        final int offset =
                clampInt(
                        (int) Math.round(
                                (position - phase)
                                        * lengths[phase]
                        ),
                        0,
                        Math.max(0, lengths[phase] - 1)
                );

        return clampInt(
                phaseStart + offset,
                0,
                Math.max(0, total - 1)
        );
    }
    /*
     * QUEUE DEFAULTS.
     *
     * These defaults were chosen visually at the canonical trick durations:
     * Tricks 1-3 use 900 ms, while Tricks 4-5 use 1420 ms. Store them as
     * the same phase-relative coordinates so changing Trick duration later
     * keeps the splice attached to the same visual point.
     */
    private int defaultQueuedExitCycle(int slot) {
        final int safeSlot = clampInt(slot, 1, 5);
        return safeSlot >= 4 ? 70 : 56;
    }

    private int defaultQueuedStartCycle(int slot) {
        final int safeSlot = clampInt(slot, 1, 5);

        if (safeSlot == 5) {
            return 30;
        }

        return safeSlot == 4 ? 25 : 23;
    }

    private int[] referenceQueuePhaseCycles(int slot) {
        final int safeSlot = clampInt(slot, 1, 5);

        /*
         * Queue defaults are authored at each finished trick's canonical
         * duration: 900 ms for Tricks 1-3, 1420 ms for Tricks 4-5. Keep that
         * reference clock stable so the stored phase-relative position maps
         * back to the same Inspector cycle after a reset or fresh install.
         */
        final int referenceMainCycles =
                safeSlot >= 4
                        ? Math.max(1, (int) Math.round(1420 / 20.0))
                        : Math.max(1, (int) Math.round(900 / 20.0));

        return new int[]{
                transitionCycles(
                        SkateScapePlugin.DEFAULT_TRICK_PRE_FRAMES,
                        SkateScapePlugin.DEFAULT_TRICK_PRE_DURATIONS_MS
                ),
                referenceMainCycles,
                Math.max(
                        1,
                        (int) Math.round(
                                SkateScapePlugin.DEFAULT_TRICK_POST_SEAM_DURATION_MS
                                        / 20.0
                        )
                ),
                transitionCycles(
                        SkateScapePlugin.DEFAULT_TRICK_POST_FRAMES,
                        SkateScapePlugin.DEFAULT_TRICK_POST_DURATIONS_MS
                )
        };
    }

    private double normalizedQueuePositionFromReference(
            int slot,
            int requestedReferenceCycle) {

        final int[] lengths = referenceQueuePhaseCycles(slot);
        int total = 0;
        for (int length : lengths) {
            total += length;
        }

        final int cycle =
                clampInt(
                        requestedReferenceCycle,
                        0,
                        Math.max(0, total - 1)
                );

        int phase = 0;
        int phaseStart = 0;
        while (phase < lengths.length - 1
                && cycle >= phaseStart + lengths[phase]) {
            phaseStart += lengths[phase++];
        }

        return phase
                + (cycle - phaseStart)
                        / (double) Math.max(1, lengths[phase]);
    }

    private void storeDefaultQueuePosition(
            int slot,
            String side) {

        final int safeSlot = clampInt(slot, 1, 5);
        final int referenceCycle =
                "exit".equals(side)
                        ? defaultQueuedExitCycle(safeSlot)
                        : defaultQueuedStartCycle(safeSlot);

        configManager.setConfiguration(
                "skatescape",
                queuePositionKey(safeSlot, side),
                normalizedQueuePositionFromReference(
                        safeSlot,
                        referenceCycle
                )
        );

        setPerTrickConfig(
                safeSlot,
                "queue",
                side + "Cycle",
                getQueuePositionCycle(
                        safeSlot,
                        side,
                        referenceCycle
                )
        );
    }
    private double defaultTuningPercent(
            int slot,
            String field) {

        final int mainCycles = defaultMainCycles(slot);
        final int oldCycle;

        if (slot == 5) {
            switch (field) {
                case "popStart":
                    return 5.0;
                case "kickStart":
                    return 10.0;
                case "kickEnd":
                    return 58.0;
                case "impossibleStart":
                    return 0.0;
                case "catch":
                    return 86.0;
                case "touchdown":
                    return 96.0;
                default:
                    return 0.0;
            }
        } else if (slot == 4) {
            switch (field) {
                case "popStart":
                    oldCycle = 6;
                    break;
                case "kickStart":
                    oldCycle = 8;
                    break;
                case "kickEnd":
                    oldCycle = 30;
                    break;
                case "impossibleStart":
                    oldCycle = 14;
                    break;
                case "catch":
                    oldCycle = 45;
                    break;
                case "touchdown":
                    oldCycle = 54;
                    break;
                default:
                    oldCycle = 0;
                    break;
            }
        } else {
            switch (field) {
                case "popStart":
                case "kickStart":
                    oldCycle = 15;
                    break;
                case "kickEnd":
                case "impossibleStart":
                case "catch":
                    oldCycle = 36;
                    break;
                case "touchdown":
                    oldCycle = 42;
                    break;
                default:
                    oldCycle = 0;
                    break;
            }
        }

        return roundPercent(
                cycleToPercent(oldCycle, mainCycles)
        );
    }

    private double defaultVarialShoveStartPercent() {
        return cycleToPercent(15, defaultMainCycles(3));
    }

    private double defaultVarialShoveEndPercent() {
        return cycleToPercent(36, defaultMainCycles(3));
    }

    private double defaultTrick5ShoveStartPercent() {
        return 34.0;
    }

    private double defaultTrick5ShoveEndPercent() {
        return 82.0;
    }

    private String defaultPoseTimingPercentages(int slot) {
        if (slot == 5) {
            /*
             * four fast 2306 launch poses, a somewhat readable Christ
             * Air hold :D, then the same 2306 poses mirrored back down. These
             * are relative weights; the runtime normalizes them to MAIN.
             */
            return "5,5,5,5,10,5,5,5,5";
        }

        if (slot != 4) {
            return "";
        }

        final int[] oldActualCycles = {
                3, 3, 3, 3,
                5, 5, 5, 5, 5, 5, 5,
                3, 3, 3, 3, 3, 3, 3, 3
        };

        return cycleWeightsToPercentList(oldActualCycles);
    }

    /*
     * Advanced Frame Timing uses a separate millisecond backing key so older
     * percentage values can never be mistaken for literal milliseconds.
     */
    private String poseTimingMsKey(int slot) {
        return perTrickKey(
                slot,
                "timing",
                "durationsMsV216"
        );
    }

