    private static String formatPoseTimingMs(String configured) {
        if (configured == null) {
            return "";
        }

        final String trimmed = configured.trim();
        if (trimmed.isEmpty()) {
            return "";
        }

        final String[] pieces = trimmed.split(",");
        final StringBuilder builder = new StringBuilder();

        try {
            for (int i = 0; i < pieces.length; i++) {
                final int value = Integer.parseInt(pieces[i].trim());

                if (value <= 0 || value > 20000) {
                    return trimmed;
                }

                if (i > 0) {
                    builder.append(',');
                }
                builder.append(value);
            }
        } catch (NumberFormatException ignored) {
            return trimmed;
        }

        return builder.toString();
    }

    private static int[] parsePoseTimingMs(String configured) {
        if (configured == null || configured.trim().isEmpty()) {
            return null;
        }

        final String[] pieces = configured.split(",");
        final int[] values = new int[pieces.length];

        try {
            for (int i = 0; i < pieces.length; i++) {
                final int value = Integer.parseInt(pieces[i].trim());

                if (value <= 0 || value > 20000) {
                    return null;
                }

                values[i] = value;
            }
        } catch (NumberFormatException ignored) {
            return null;
        }

        return values;
    }

    String getPoseTimingMs(int slot) {
        return formatPoseTimingMs(getPoseTimingMsRaw(slot));
    }

    String getPoseTimingWarning(int slot) {
        final int safeSlot = clampInt(slot, 1, 5);

        if (!getAdvancedPoseTiming(safeSlot)) {
            return "";
        }

        final int[] values = parsePoseTimingMs(getPoseTimingMs(safeSlot));
        if (values == null || values.length == 0) {
            return "";
        }

        long totalMs = 0L;
        for (int value : values) {
            totalMs += value;
        }

        final int trickDurationMs = getTuningInt(safeSlot, "durationMs");
        if (totalMs > trickDurationMs) {
            return "Frame timing totals "
                    + totalMs
                    + " ms - Trick duration is "
                    + trickDurationMs
                    + " ms.";
        }

        return "";
    }

    private static double cycleToPercent(
            int cycle,
            int totalCycles) {

        if (totalCycles <= 0) {
            return 0.0;
        }

        return clampDouble(
                cycle * 100.0 / totalCycles,
                0.0,
                100.0
        );
    }

    private static String formatPercent(double value) {
        String formatted = String.format(
                Locale.ROOT,
                "%.1f",
                roundPercent(value)
        );

        while (formatted.indexOf('.') >= 0
                && formatted.endsWith("0")) {
            formatted = formatted.substring(0, formatted.length() - 1);
        }

        if (formatted.endsWith(".")) {
            formatted = formatted.substring(0, formatted.length() - 1);
        }

        return formatted;
    }

    /*
     * the Trick Lab exposes percentage timing to one decimal place.
     * A 0.1% step is still far finer than one client cycle at the standard
     * trick durations, while keeping the editor cleaner and easier to tune.
     */
    private static double roundPercent(double value) {
        final double rounded = Math.round(value * 10.0) / 10.0;
        return Math.abs(rounded) < 0.05 ? 0.0 : rounded;
    }

    private static String formatPosePercentageList(String configured) {
        if (configured == null || configured.trim().isEmpty()) {
            return "";
        }

        final String[] pieces = configured.split(",");
        final StringBuilder builder = new StringBuilder();

        try {
            for (int i = 0; i < pieces.length; i++) {
                final double value = Double.parseDouble(pieces[i].trim());

                if (!Double.isFinite(value)
                        || value < 0.0
                        || value > 100.0) {
                    return configured.trim();
                }

                if (i > 0) {
                    builder.append(',');
                }

                builder.append(formatPercent(value));
            }
        } catch (NumberFormatException ignored) {
            /*
             * Do not fight the user while they are editing an incomplete
             * text value. The timeline parser will keep its existing fallback
             * behavior until the text becomes valid again.
             */
            return configured.trim();
        }

        return builder.toString();
    }

    private static String cycleWeightsToPercentList(int[] cycles) {
        if (cycles == null || cycles.length == 0) {
            return "";
        }

        int total = 0;
        for (int cycle : cycles) {
            total += Math.max(1, cycle);
        }

        total = Math.max(1, total);

        final StringBuilder builder = new StringBuilder();
        for (int i = 0; i < cycles.length; i++) {
            if (i > 0) {
                builder.append(',');
            }

            builder.append(
                    formatPercent(
                            Math.max(1, cycles[i]) * 100.0 / total
                    )
            );
        }

        return builder.toString();
    }

    private static double clampDouble(
            double value,
            double min,
            double max) {

        if (max < min) {
            return min;
        }

        return Math.max(min, Math.min(max, value));
    }

