                    "skatescape",
                    "tuningTrick4ImpossibleDegreesV147",
                    slot == 4
                            ? getTrick4ImpossibleDegrees()
                            : 360
            );
            configManager.setConfiguration(
                    "skatescape",
                    "tuningImpossibleStartCycleV132",
                    slot == 2
                            ? (double) getShoveItDegrees()
                            : slot == 3
                                    ? (double) getVarialShoveDegrees()
                                    : slot == 5
                                            ? (double) getTrick5ShoveDegrees()
