                    "skatescape",
                    "tuningVarialShoveStartCycleV142",
                    slot == 5
                            ? getTrick5ShoveStartPercent()
                            : getVarialShoveStartPercent()
            );
            configManager.setConfiguration(
                    "skatescape",
                    "tuningVarialShoveEndCycleV142",
                    slot == 5
                            ? getTrick5ShoveEndPercent()
                            : getVarialShoveEndPercent()
